from collections import OrderedDict

class TTL Cache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.stats = {'hits': 0, 'misses': 0, 'evictions': 0, 'expirations': 0}
        self.cache = OrderedDict()

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.cache:
            current_time = self.clock()
            new_expiration = current_time + self.ttl
            self.cache[key] = (value, new_expiration)
            self.cache.move_to_end(key)
            return

        current_time = self.clock()
        if len(self.cache) >= self.capacity:
            expired_keys = []
            for k in list(self.cache.keys()):
                if current_time >= self.cache[k][1]:
                    expired_keys.append(k)
            for k in expired_keys:
                del self.cache[k]
                self.stats['expirations'] += 1
            if len(self.cache) >= self.capacity:
                lru_key = next(iter(self.cache.keys()))
                del self.cache[lru_key]
                self.stats['evictions'] += 1

        new_expiration = current_time + self.ttl
        self.cache[key] = (value, new_expiration)
        self.cache.move_to_end(key)

    def get(self, key, default=None):
        if self.capacity == 0:
            self.stats[' misses'] += 1
            return default
        current_time = self.clock()
        if key in self.cache:
            value, expiration_time = self.cache[key]
            if current_time >= expiration_time:
                del self.cache[key]
                self.stats['expirations'] += 1
                self.stats[' misses'] += 1
                return default
            else:
                self.cache.move_to_end(key)
                self.stats['hits'] += 1
                return value
        else:
            self.stats[' misses'] += 1
            return default

    def __len__(self):
        current_time = self.clock()
        count = 0
        for key in self.cache:
            if current_time < self.cache[key][1]:
                count += 1
        return count

    def stats(self):
        return self.stats.copy()
