def summarize ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    sortednums = sorted(set(nums))
    start = sortednums[0]
    current = start
    res = []
    for i in range(1, len(sortednums)):
        if sortednums[i] == current + 1:
            current = sortednums[i]
        else:
            if current - start >= 2:
                res.append(f"{start}..{current}")
            elif current - start == 1:
                res.append(str(start))
                res.append(str(current))
            else:
                res.append(str(start))
            start = sortednums[i]
            current = start
    if current - start >= 2:
        res.append(f"{start}..{current}")
    elif current - start == 1:
        res.append(str(start))
        res.append(str(current))
    else:
        res.append(str(start))
    return ','.join(res)
